-- Lavender Floral Arena | Standalone iPad Adaptive
-- Based on the user's portable JSON and the Mahiru adaptive texture replacement approach.
-- Client-side only; no official RIVALS import support is implied.
local env = (getgenv and getgenv()) or _G
local KEY = "__LAVENDER_FLORAL_ARENA_V1"
if env[KEY] and env[KEY].stop then env[KEY].stop() end
local running = true
local connections, original = {}, setmetatable({}, {__mode="k"})
local function stop()
 running = false
 for _,c in ipairs(connections) do pcall(function() c:Disconnect() end) end
 for obj,props in pairs(original) do
  if obj and obj.Parent then for prop,value in pairs(props) do pcall(function() obj[prop]=value end) end end
 end
end
env[KEY] = {stop=stop}
local function decode(s)
 local chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
 s=s:gsub('[^'..chars..'=]','')
 local bits=s:gsub('.',function(x)
  if x=='=' then return '' end
  local n=chars:find(x,1,true)-1; local b=''
  for i=6,1,-1 do b=b..(math.floor(n/2^(i-1))%2) end
  return b
 end)
 return bits:gsub('%d%d%d%d%d%d%d%d',function(b)
  local n=0; for i=1,8 do n=n+(b:sub(i,i)=='1' and 2^(8-i) or 0) end
  return string.char(n)
 end)
end
local IMAGE_BASE64 = [==[

]==]
local asset
if type(writefile)=='function' and type(getcustomasset or getsynasset)=='function' then
 local ok,result=pcall(function()
  local bytes=decode(IMAGE_BASE64)
  if bytes:sub(1,3) ~= string.char(255,216,255) then error('Invalid JPEG bytes') end
  local file='lavender_floral_arena_v1.jpg'
  writefile(file,bytes)
  return (getcustomasset or getsynasset)(file)
 end)
 if ok then asset=result else warn('[Lavender Floral] '..tostring(result)) end
else warn('[Lavender Floral] Executor needs writefile and getcustomasset/getsynasset') end
local TARGET='7658055825' -- texture ID used by the reference Mahiru adaptive script; may not exist on every RIVALS map
local function id(v)
 if type(v)~='string' then return nil end
 return v:match('rbxassetid://(%d+)') or v:match('[?&]id=(%d+)') or v:match('(%d+)')
end
local queue,head,queued={},1,setmetatable({}, {__mode='k'})
local function remember(obj,prop)
 local t=original[obj]; if not t then t={};original[obj]=t end
 if t[prop]==nil then pcall(function() t[prop]=obj[prop] end) end
end
local function enqueue(obj)
 if not asset or not obj:IsDescendantOf(workspace) or queued[obj] then return end
 local prop
 if obj:IsA('Texture') or obj:IsA('Decal') then prop='Texture'
 elseif obj:IsA('MeshPart') then prop='TextureID' end
 if prop then
  local ok,v=pcall(function() return obj[prop] end)
  if ok and id(v)==TARGET then queued[obj]=true; queue[#queue+1]={obj,prop} end
 end
end
local function applyColors(obj)
 if not obj:IsA('BasePart') or not obj:IsDescendantOf(workspace) then return end
 local name=obj.Name:lower()
 local color
 if name:find('floor',1,true) or name:find('ground',1,true) then color=Color3.fromRGB(220,211,233)
 elseif name:find('wall',1,true) then color=Color3.fromRGB(220,211,233)
 elseif name:find('accent',1,true) then color=Color3.fromRGB(166,155,185) end
 if color then
  remember(obj,'Color');remember(obj,'Material')
  pcall(function() obj.Color=color;obj.Material=Enum.Material.SmoothPlastic end)
  -- Texture tiles on recognized floors/walls; avoids covering every part in the map.
  if asset and (name:find('floor',1,true) or name:find('wall',1,true)) then
   local face= name:find('floor',1,true) and Enum.NormalId.Top or Enum.NormalId.Front
   local tex=obj:FindFirstChild('LavenderFloralOverlay')
   if not tex then
    tex=Instance.new('Texture');tex.Name='LavenderFloralOverlay';tex.Face=face
    tex.StudsPerTileU=8;tex.StudsPerTileV=8;tex.Texture=asset;tex.Parent=obj
    local t=original[obj];t.__overlay=tex
   end
  end
 end
end
-- Only named geometry and the known reference texture ID are changed.
local function inspect(obj) enqueue(obj);applyColors(obj) end
local function runScan()
 local all=workspace:GetDescendants()
 for i,obj in ipairs(all) do if not running then return end;inspect(obj);if i%200==0 then task.wait() end end
end
local function notify(msg)
 pcall(function() game:GetService('StarterGui'):SetCore('SendNotification',{Title='Lavender Floral Arena',Text=msg,Duration=5}) end)
end
local gui=Instance.new('ScreenGui');gui.Name='LavenderFloralArenaUI';gui.ResetOnSpawn=false
pcall(function() gui.Parent=game:GetService('CoreGui') end)
if not gui.Parent then gui.Parent=game:GetService('Players').LocalPlayer:WaitForChild('PlayerGui') end
local frame=Instance.new('Frame');frame.Size=UDim2.fromOffset(240,122);frame.Position=UDim2.new(0.5,-120,0.1,0);frame.BackgroundColor3=Color3.fromRGB(27,23,34);frame.Parent=gui
Instance.new('UICorner',frame).CornerRadius=UDim.new(0,12)
local title=Instance.new('TextLabel');title.Size=UDim2.new(1,0,0,36);title.BackgroundTransparency=1;title.Text='💜 Lavender Floral Arena';title.TextColor3=Color3.fromRGB(230,211,247);title.Font=Enum.Font.GothamBold;title.TextSize=16;title.Parent=frame
local function button(label,x,fn)
 local b=Instance.new('TextButton');b.Size=UDim2.fromOffset(104,45);b.Position=UDim2.fromOffset(x,52);b.BackgroundColor3=Color3.fromRGB(166,155,185);b.TextColor3=Color3.fromRGB(20,16,26);b.Text=label;b.TextSize=15;b.Font=Enum.Font.GothamBold;b.Parent=frame
 Instance.new('UICorner',b).CornerRadius=UDim.new(0,8)
 b.MouseButton1Click:Connect(fn)
end
local active=false
button('APPLY',10,function()
 if active then notify('Already applied') return end
 active=true;notify(asset and 'Applying lavender textures...' or 'Image unavailable: applying lavender colors only')
 task.spawn(runScan)
 local c=workspace.DescendantAdded:Connect(function(obj) if running then task.defer(function() if running and obj.Parent then inspect(obj) end end) end end)
 table.insert(connections,c)
 task.spawn(function()
  while running do
   for _=1,8 do
    local item=queue[head];if not item then break end
    head=head+1;local obj,prop=item[1],item[2]
    if obj and obj.Parent then
     pcall(function() if id(obj[prop])==TARGET then remember(obj,prop);obj[prop]=asset end end)
    end
   end
   if head>1000 then local q={};for i=head,#queue do q[#q+1]=queue[i] end;queue=q;head=1 end
   task.wait(.10)
  end
 end)
end)
button('REMOVE',126,function()
 stop()
 for obj,props in pairs(original) do if props.__overlay then pcall(function() props.__overlay:Destroy() end) end end
 gui:Destroy();env[KEY]=nil
end)
notify('Ready! Tap APPLY')
